import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·24","description":"易小帖 - 卷四·24","frontmatter":{"title":"卷四·24","description":"易小帖 - 卷四·24"},"headers":[],"relativePath":"zh/classics/yixiaotie/118.md","filePath":"zh/classics/yixiaotie/118.md"}'),o={name:"zh/classics/yixiaotie/118.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·24",tabindex:"-1"},[r("卷四·24 "),e("a",{class:"header-anchor",href:"#卷四·24","aria-label":"Permalink to “卷四·24”"},"​")],-1),e("p",null,"朋字從來作不好字，故曰朋字未正。漢後所謂朋黨可驗。況陰聚為朋，則純乎小人矣，是以西南為三女之位，則名朋。東北為三男之位，即喪朋。此易明也。朱氏祖程氏之說，不以為卦位而以為方位，竟曰：西南是陰方，東北是陽方。夫以方位論，則東南為陽，西北為陰。夫人而知之也。少年教方名便知此義，今一反而以南為陰，以北為陽，則夫子《說卦》曰：「聖人南面而聽天下，向明而治。」謂之向陰而治可乎？然程氏猶知喪朋是慶，而朱氏必以得朋為慶，是反夫子語也。夫子語何可反也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
